// Тикет #43533eab · 43533eabf7a5e241a175df1d (поиск «רשימת התפילות», S-27, Figma 454:8361) — עבר QA 14.10.2026 (iPhone, TestFlight 1.0.0 (20)).
// Кейс .qa/tests/prayer-catalog/PC-03-search-placeholder-rtl.md.
// מה רצוי: «בשדה החיפוש ה-placeholder «חיפוש» מיושר לימין, ומשמאל לו (בצד הימני של השדה) אייקון זכוכית מגדלת … טקסט שהמשתמש מקליד בעברית מתחיל מימין.»
// Факт 14.10: placeholder «חיפוש» и лупа справа (43533eab-ios-b20-search-placeholder-right.png); ввод «מנ» начинается справа,
//   фильтр — «מנחה» и «שיעורי תורה» (43533eab-ios-b20-search-typing-rtl.png).
// ОБНОВЛЕНО 25.10 (#8a7f1a, עבר QA): «ניקוי החיפוש» нажимается при открытой клавиатуре, без обхода.
// ОБНОВЛЕНО 21.10 (#0f8f122d, עבר QA): поиск фильтрует и «שיעורי תורה» → по «מנ» только «מנחה» (F-40 AC5; факт 21.10, 2110-0f8f122d-*.png).
// Позиция букв внутри TextField через accessibility не видна → выравнивание: если placeholder/ввод — отдельный текст, по рамке;
//   иначе @manual-check (сверить со скрином). Фильтр — автоматически.
import { driver, expect } from '@wdio/globals';
import { byText, byLabel, tapLabel } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { shown } from '../_lib/app-0710.ts';
import { rectOf, staticText } from '../_lib/app-1310.ts';
import { openPrayersTab, prayersSearchField, fieldPlaceholder, fieldValue } from '../_lib/app-1410.ts';

/** Текст (placeholder или введённый) — отдельный элемент внутри поля, центр правее середины поля. */
async function rightInField(text: string, where: string) {
  const field = await prayersSearchField();
  const f = await rectOf(field);
  const t = staticText(text);
  if (!(await shown(t))) { console.log(`[PC-03] ${where}: «${text}» внутри TextField — @manual-check выравнивание вправо по скрину`); return; }
  const r = await rectOf(t);
  if (r.width >= f.width * 0.9) { console.log(`[PC-03] ${where}: рамка текста на всю ширину поля — @manual-check`); return; }
  expect(r.x + r.width / 2).toBeGreaterThan(f.x + f.width / 2);
}

describe('Поиск экрана «תפילות» RTL (#43533eab)', () => {
  afterEach(async () => {
    const clear = await byLabel('ניקוי החיפוש');
    if (await clear.isDisplayed().catch(() => false)) await clear.click().catch(() => {});
    await toHome().catch(() => {});
  });

  it('PC-03 Placeholder «חיפוש» справа, лупа; ввод «מנ» справа → только «מנחה» (без «שיעורי תורה», #0f8f122d) #43533eab #0f8f122d @prod-safe @manual-check', async () => {
    await openPrayersTab();
    const field = await prayersSearchField();
    await field.clearValue();

    // 1. Placeholder «חיפוש» (атрибут поля или отдельный текст) — справа.
    const ph = await fieldPlaceholder(field);
    expect((await shown(staticText('חיפוש'))) || ph.includes('חיפוש')).toBe(true);
    await rightInField('חיפוש', 'placeholder');
    // Лупа: отдельной подписи у иконки нет (14.10) — @manual-check по скрину 43533eab-ios-b20-search-placeholder-right.png.
    console.log('[PC-03] лупа справа в поле — @manual-check по скрину');

    // 2. Ввод «מנ» → значение поля «מנ», текст справа.
    await field.setValue('מנ');
    await driver.waitUntil(async () => (await fieldValue(field)).includes('מנ'), { timeout: 10000, timeoutMsg: 'в поле нет «מנ»' });
    await rightInField('מנ', 'ввод');

    // 3. Фильтр: только «מנחה»; «שיעורי תורה», «שחרית», «ערבית» скрыты (#0f8f122d, факт 21.10; до фикса 14.10 «שיעורי תורה» оставалась).
    await expect(byText('מנחה')).toBeDisplayed({ wait: 10000 });
    await expect(byText('שיעורי תורה')).not.toBeDisplayed();
    await expect(byText('שחרית')).not.toBeDisplayed();
    await expect(byText('ערבית')).not.toBeDisplayed();

    // 4. «ניקוי החיפוש» — ОДНО нажатие при открытой клавиатуре → поле пустое (#8a7f1a, עבר QA 25.10; обход «скрыть клавиатуру» убран).
    await tapLabel('ניקוי החיפוש');
    await driver.waitUntil(async () => !(await fieldValue(field)).includes('מנ'), { timeout: 10000, timeoutMsg: 'поле не очистилось' });
  });
});
